  '190°C fırında her tarafı kızarana kadar pişirin.': 'اخبزيها على 190°م حتى تتحمر من كل الجهات.',
  '190°C fırında hindi tamamen pişene kadar pişirip dinlendirin.': 'اخبزيه على 190°م حتى ينضج الديك الرومي تمامًا ثم اتركيه يرتاح.',
  '190°C fırında iki tarafı kızarana kadar 20-25 dakika pişirin.': 'اخبزيها على 190°م لمدة 20-25 دقيقة حتى تتحمر من الجهتين.',
  '190°C fırında iki tarafı kızarana kadar 25 dakika pişirin.': 'اخبزيها على 190°م لمدة 25 دقيقة حتى تتحمر من الجهتين.',
  '190°C fırında iki yüzünü çevirerek kızartın.': 'اخبزيها على 190°م مع قلبها مرة حتى تتحمر من الجهتين.',
  '190°C fırında içi tamamen pişip üzeri kızarana kadar pişirin.': 'اخبزيه على 190°م حتى ينضج من الداخل تمامًا ويتحمر الوجه.',
  '190°C fırında içleri pişip kabukları kızarana kadar pişirin.': 'اخبزيها على 190°م حتى تنضج من الداخل وتتحمر القشرة.',
  '190°C fırında içleri tamamen pişene kadar yaklaşık 25 dakika pişirin.': 'اخبزيها على 190°م نحو 25 دقيقة حتى تنضج من الداخل تمامًا.',
  '190°C fırında kabaklar yumuşayana kadar 25-30 dakika pişirin.': 'اخبزيها على 190°م لمدة 25-30 دقيقة حتى تلين الكوسا.',
  '190°C fırında köftelerin içi tamamen pişene kadar pişirin.': 'اخبزيها على 190°م حتى تنضج الكفتة من الداخل تمامًا.',
  '190°C fırında köftelerin içi tamamen pişene kadar yaklaşık 30 dakika pişirin.': 'اخبزيها على 190°م نحو 30 دقيقة حتى تنضج الكفتة من الداخل تمامًا.',
  '190°C fırında peynir eriyip kızarana kadar 15 dakika pişirin.': 'اخبزيها على 190°م لمدة 15 دقيقة حتى يذوب الجبن ويتحمر.',
  '190°C fırında tavuk tamamen pişene kadar pişirin.': 'اخبزيه على 190°م حتى ينضج الدجاج تمامًا.',
  '190°C fırında yumurta tamamen pişene kadar pişirin.': 'اخبزيها على 190°م حتى ينضج البيض تمامًا.',
