  'Düzensiz veya seyrek adet, sivilce, tüylenme ve kilo artışı görülebilir.': 'قد تظهر دورات غير منتظمة أو متباعدة وحب الشباب وزيادة الشعر وزيادة الوزن.',
  'Düzleşme 4 aydan sonra artıyorsa veya alın/kulaklarda asimetri varsa.': 'إذا ازداد التسطح بعد الشهر الرابع أو كان الجبين/الأذنان غير متناظرين.',
