  'Düşünce': 'الفكر',
  'DİKKAT: Yedekte bulunan alanlardaki mevcut kayıtlar yedekteki değerlerle değiştirilecek. Yedekte olmayan alanlardaki kayıtlar korunur. İşlem öncesi yine de mevcut verilerinizi ayrıca yedekleyin.': 'تحذير: ستُستبدل السجلات الحالية في المجالات المضمَّنة في النسخة الاحتياطية بقيم النسخة. السجلات في المجالات غير المضمَّنة تبقى. ومع ذلك انسخي بياناتك الحالية احتياطيًا بشكل منفصل قبل المتابعة.',
  'DİKKAT: Çocuk 49–72 aylık yakalama aşılaması yaş grubunda olabilir. İkinci suçiçeği dozu için aile hekiminizle görüşün. Bu uyarı aşı yapılmadığı anlamına gelmez.': 'ملاحظة: قد يكون الطفل ضمن فئة التطعيم التعويضي من 49 إلى 72 شهرًا. تحدثي مع طبيب الأسرة عن الجرعة الثانية من لقاح جدري الماء. هذا التحذير لا يعني أن اللقاح لم يُعطَ.',
