  'Fizyolojik sarılık genellikle 2–3. günde başlar, 1–2 haftada geçer.': 'يبدأ اليرقان الفسيولوجي عادةً في اليوم 2–3 ويزول خلال 1–2 أسبوع.',
  'Flutter analiz, otomatik test, APK/AAB, gerçek cihaz ve iOS TestFlight doğrulaması yapılmadı.': 'لم يتم تحليل Flutter أو الاختبارات الآلية أو APK/AAB أو التحقق على جهاز حقيقي أو iOS TestFlight.',
  'Flutter analyze': 'Flutter analyze',
  'Flutter analyze temiz': 'Flutter analyze نظيف',
  'Flutter test başarılı': 'نجحت اختبارات Flutter',
  'Folik asit desteği gebelikten en az 1 ay önce başlanıp ilk 3 ay sürdürülmesi önerilir; nöral tüp defektlerini azaltır.': 'يُوصى بحمض الفوليك قبل الحمل بشهر على الأقل حتى نهاية الشهر الثالث؛ فهو يقلل عيوب الأنبوب العصبي.',
  'Folik asit dozunu hekimine danış (risk durumunda daha yüksek doz gerekebilir).': 'اسألي الطبيب عن جرعة حمض الفوليك (قد تلزم جرعة أعلى عند وجود خطر).',
  'Folik asit kullanmaya devam et; ilaçları doktoruna sormadan kullanma.': 'استمري في حمض الفوليك؛ ولا تتناولي أدوية دون استشارة الطبيب.',
  'Folik asit, demir, D vitamini, doğum kontrol hapı, tiroid ilacı… hepsini ekleyebilirsin.': 'حمض الفوليك، الحديد، فيتامين د، حبوب منع الحمل، دواء الغدة الدرقية… يمكنك إضافة كل ذلك.',
  'Folyosuz olarak 12–15 dakika daha, balık beyazlaşıp kolayca dağılana kadar pişirin ve 5 dakika dinlendirip servis edin.': 'اخبزيه مكشوفًا 12–15 دقيقة أخرى حتى يبيضّ السمك ويتفتت بسهولة؛ واتركيه 5 دقائق ثم قدّميه.',
  'Folyoyu açıp 10 dakika daha kızartın, 15 dakika dinlendirin.': 'أزيلي ورق الألمنيوم وحمّريه 10 دقائق أخرى، ثم اتركيه 15 دقيقة.',
  'Folyoyu açıp 15 dakika kızartın.': 'أزيلي ورق الألمنيوم وحمّريها 15 دقيقة.',
  'Folyoyu açıp 220 °C\'de 15 dakika kızartın.': 'أزيلي ورق الألمنيوم وحمّريه على 220 °م مدة 15 دقيقة.',
  'Folyoyu kaldırıp 15 dakika daha, köfteler kızarana kadar pişirin.': 'أزيلي ورق الألمنيوم واخبزيها 15 دقيقة أخرى حتى تتحمر الكفتة.',
  'Folyoyu kaldırıp 15 dakika daha, üzeri kızarana ve patatesler yumuşayana kadar pişirin.': 'أزيلي ورق الألمنيوم واخبزيها 15 دقيقة أخرى حتى يتحمر الوجه وتلين البطاطا.',
  'Folyoyu kaldırıp kalan kaşarı serpin, 15 dakika daha üzeri kızarana ve patatesler bıçakla kolayca delinene kadar pişirin; 10 dakika dinlendirip dilimleyin.': 'ارفعي ورق الألومنيوم ورشّي باقي القشقوان واخبزيه 15 دقيقة أخرى حتى يتحمر ويخترق السكين البطاطا بسهولة؛ واتركيه 10 دقائق ثم قطّعيه.',
