  'Fırın kabına sırayla sos, lazanya yaprağı, beşamel ve peynir dizin; 3 kat tekrarlayın.': 'رصّي في طبق الفرن بالترتيب: الصلصة ثم ورق اللازانيا ثم البشاميل ثم الجبن؛ وكرّري 3 طبقات.',
