  'Gelişimsel hazır oluşa uygun ek gıdaları güvenli kıvamda sunun; anne sütü veya uygun mama devam eder. Yeni besinlerde alerji belirtilerini gözlemleyin. Bal vermeyin.': 'قدّمي الأطعمة الصلبة وفق الاستعداد وبقوام آمن؛ ويستمر حليب الأم أو الحليب الصناعي. راقبي علامات الحساسية مع الأطعمة الجديدة. لا تعطي العسل.',
