  'Kan şekeri düşük. Hızlı emilen şeker al, 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'سكر الدم منخفض. تناولي سكرًا سريع المفعول وأعيدي القياس بعد 15 دقيقة؛ إن لم يتحسن، راجعي طبيبك.',
  'Kan şekeri düşük: Hızlı emilen şeker al (ör. yarım bardak meyve suyu), 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'سكر الدم منخفض: تناولي سكرًا سريع المفعول (مثل نصف كوب عصير) وأعيدي القياس بعد 15 دقيقة؛ إن لم يتحسن، راجعي طبيبك.',
