  'Tatlıyı ödül olarak kullanma; şekerli içecekleri sınırla.': 'لا تستخدمي الحلوى مكافأة؛ وقلّلي المشروبات المحلاة.',
  'Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin.': 'إذا ازدحمت المقلاة يُسلق السمك بدل أن يتحمر؛ اطبخيه على دفعتين عند الحاجة.',
  'Tavada 2 yemek kaşığı zeytinyağıyla patlıcanları orta ateşte 8 dakika, her yüzü hafif kızarana kadar soteleyin.': 'قلّبي الباذنجان في مقلاة بملعقتين كبيرتين من زيت الزيتون على نار متوسطة 8 دقائق حتى يتحمر قليلًا من كل جهة.',
  'Tavada 2 yemek kaşığı zeytinyağıyla pırasa, havuç ve sarımsağı 5 dakika soteleyin; sıcak suyu ve yarım çay kaşığı tuzu ekleyip kapağı kapalı 8 dakika pişirin.': 'قلّبي الكرّاث والجزر والثوم في ملعقتين كبيرتين من زيت الزيتون 5 دقائق؛ ثم أضيفي الماء الساخن ونصف ملعقة صغيرة ملح واطبخيها مغطاة 8 دقائق.',
  'Tavada her yüzü 2 dakika kızartın.': 'حمّصيها في المقلاة دقيقتين لكل وجه.',
  'Tavada her yüzü 3 dakika ısıtın.': 'سخّنيها في المقلاة 3 دقائق لكل وجه.',
  'Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.': 'حمّري الجهتين في المقلاة على نار متوسطة؛ واطبخي 12–18 دقيقة حسب السماكة.',
  'Tavada pizza ekmeği': 'خبز البيتزا في المقلاة',
  'Tavada tereyağını eritin, sebzeyi ekleyip suyunu çekene kadar 4–5 dakika soteleyin.': 'أذيبي الزبدة في المقلاة وأضيفي الخضار وقلّبيها 4–5 دقائق حتى يتبخر الماء.',
  'Tavada tereyağını eritip sucukları 2 dakika çevirin.': 'ذوّبي الزبدة في المقلاة وقلّبي السجق دقيقتين.',
  'Tavada yağı kızdırın.': 'سخّني الزيت في المقلاة.',
  'Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.': 'سخّني الزيت في المقلاة وقلّبي الدجاج على نار عالية حتى يتلون.',
  'Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.': 'ليّني البصل في زيت الزيتون 3 دقائق، وأضيفي معجون الطماطم وقلّبيه دقيقة؛ ثم أضيفي الطماطم المبشورة والماء الساخن واتركيها تغلي 3 دقائق.',
  'Tavada zeytinyağıyla tavukları yüksek ateşte 6 dakika soteleyin, tabağa alın.': 'قلّبي الدجاج في زيت الزيتون على نار عالية 6 دقائق وانقليه إلى طبق.',
  'Tavada üzerine ağırlık koyarak her yüzü 2 dakika kızartın.': 'حمّصيها في المقلاة مع وضع ثقل فوقها دقيقتين لكل وجه.',
  'Tavaya ince pudra şekeri serpip orta ateşte karamelize edin.': 'رشّي طبقة رقيقة من السكر البودرة في المقلاة وكرمليها على نار متوسطة.',
  'Tavaya sebzeleri yayıp balıkları üzerine koyun.': 'افردي الخضار في المقلاة وضعي السمك فوقها.',
  'Tavayı iyice kızdırın; sebzeler kızarsın.': 'سخّني المقلاة جيدًا حتى تتحمر الخضار.',
  'Tavuk 74°C iç sıcaklığa ulaşınca ocaktan alın.': 'ارفعيه عن النار عندما تصل حرارة الدجاج الداخلية إلى 74°م.',
  'Tavuk bagetleri ve patatesleri yağ, kekik ve biberle harmanlayıp tepsiye tek kat dizin.': 'اخلطي الأفخاذ والبطاطا بالزيت والزعتر والفلفل وافرديها طبقة واحدة في الصينية.',
