  'Tavuk iç sıcaklığı en az 74 °C olana dek yaklaşık 35–45 dakika pişirin.': 'اخبزيه نحو 35–45 دقيقة حتى تصل حرارة الدجاج الداخلية إلى 74 °م على الأقل.',
  'Tavuk iç sıcaklığı en az 74 °C olana kadar yaklaşık 40–45 dakika pişirin.': 'اخبزيه نحو 40–45 دقيقة حتى تصل حرارة الدجاج الداخلية إلى 74 °م على الأقل.',
