  'Tavuk suyunu, didiklenmiş tavuğu ve şehriyeyi ekleyin.': 'أضيفي مرق الدجاج والدجاج المفتت والشعيرية.',
  'Tavuk tamamen pişene kadar yaklaşık 20 dakika kısık ateşte pişirin.': 'اطبخيه على نار هادئة نحو 20 دقيقة حتى ينضج الدجاج تمامًا.',
  'Tavuk tamamen pişince dilimlenmiş mantarı ekleyin.': 'عندما ينضج الدجاج تمامًا أضيفي الفطر المقطع شرائح.',
  'Tavuk tamamen pişip içi pembe kalmayana kadar 40-45 dakika pişirin.': 'اخبزيها 40-45 دقيقة حتى ينضج الدجاج تمامًا ولا يبقى لون وردي في الداخل.',
  'Tavuk tamamen pişmiş olmalı; kemik bulunmamalı.': 'يجب أن ينضج الدجاج تمامًا؛ ويجب ألا تبقى عظام.',
  'Tavuk tantuni': 'طنطوني الدجاج',
  'Tavuk ve biberleri şişlere dizip 200°C fırında yaklaşık 20–25 dakika pişirin.': 'اشكّي الدجاج والفلفل في الأسياخ واخبزيها على 200°م نحو 20–25 دقيقة.',
  'Tavuk ve brokoliyi sosa ekleyin; tuz ve karabiberle tatlandırıp 3 dakika pişirin.': 'أضيفي الدجاج والبروكلي إلى الصلصة؛ وتبّلي بالملح والفلفل الأسود واطبخي 3 دقائق.',
