  'Tavukları geri ekleyin, sosu döküp 1–2 dakika parlak ve koyu kıvama gelene kadar karıştırın.': 'أعيدي الدجاج واسكبي الصلصة وقلّبي 1–2 دقيقة حتى تلمع وتتكثف.',
