  'Tavukları sosla kaplayıp 20 dakika buzdolabında bekletin.': 'غطّي الدجاج بالصلصة واتركيه في الثلاجة 20 دقيقة.',
  'Tavukları tavaya geri alın; tuz, karabiber ve kekikle tatlandırıp kısık ateşte 5 dakika pişirin.': 'أعيدي الدجاج إلى المقلاة؛ وتبّليه بالملح والفلفل الأسود والزعتر واطبخيه على نار هادئة 5 دقائق.',
  'Tavukları una, yumurtaya, sonra galeta-parmesan karışımına bulayın.': 'غلّفي الدجاج بالدقيق ثم البيض ثم خليط البقسماط والبارميزان.',
