  'Un ve yağı ekleyip yumuşak hamur yoğurun, 45 dakika mayalandırın.': 'أضيفي الدقيق والزيت واعجني عجينة طرية واتركيها تختمر 45 دقيقة.',
  'Un ve şeker içermez.': 'لا تحتوي على دقيق أو سكر.',
  'Un, ceviz ve kabartma tozunu ekleyip yumuşak hamur elde edin.': 'أضيفي الدقيق والجوز والبيكنج باودر لتحصلي على عجينة طرية.',
  'Un, kabartma tozu ve ince kıyılmış cevizi ekleyip hamur yapın': 'أضيفي الدقيق والبيكنج باودر والجوز المفروم ناعمًا لتحصلي على عجينة',
  'Un, kabartma tozu ve tarçını ekleyip karıştırın.': 'أضيفي الدقيق والبيكنج باودر والقرفة واخلطي.',
  'Un, kabartma tozu ve tarçını eleyerek ekleyin; cevizi un serpip ilave edin.': 'انخلي الدقيق والبيكنج باودر والقرفة وأضيفيها؛ ورشّي الدقيق على الجوز ثم أضيفيه.',
  'Un, kabartma tozu ve tarçını karışıma katın.': 'أضيفي الدقيق والبيكنج باودر والقرفة إلى الخليط.',
  'Un, kabartma tozu ve vanilini ekleyin.': 'أضيفي الدقيق والبيكنغ باودر والفانيليا.',
  'Un, karbonat ve tarçını ekleyin.': 'أضيفي الدقيق وبيكربونات الصودا والقرفة.',
  'Un, maya ve suyu karıştırıp zeytinyağıyla yumuşak hamur yoğurun.': 'اخلطي الدقيق والخميرة والماء واعجني عجينة طرية بزيت الزيتون.',
  'Un, maya, şeker, tuz ve suyla akışkan hamur yapıp 1 saat mayalandırın.': 'اصنعي عجينة سائلة من الدقيق والخميرة والسكر والملح والماء واتركيها تختمر ساعة.',
  'Un, maya, şeker, tuz, su ve yağla hamur yoğurup 1 saat mayalandırın.': 'اعجني الدقيق والخميرة والسكر والملح والماء والزيت واتركي العجينة تختمر ساعة.',
  'Un, maya, şeker, tuz, süt, yağ ve yumurta beyazıyla yumuşak hamur yoğurun, 1 saat mayalandırın.': 'اعجني عجينة طرية بالدقيق والخميرة والسكر والملح والحليب والزيت وبياض البيض واتركيها تختمر ساعة.',
  'Un, su ve tuzla yumuşak hamur yoğurup 20 dakika dinlendirin.': 'اعجني عجينة طرية بالدقيق والماء والملح واتركيها 20 دقيقة.',
  'Un, tereyağı, şeker ve yulafı parmak uçlarıyla kırıntı kıvamına getirin.': 'افركي الدقيق والزبدة والسكر والشوفان بأطراف أصابعك حتى يصبح فتاتًا.',
  'Un, tuz ve küp tereyağını parmak uçlarıyla ovalayın; yumurta ve suyu ekleyip toparlayın, 30 dakika buzdolabında dinlendirin.': 'افركي الدقيق والملح ومكعبات الزبدة بأطراف أصابعك؛ وأضيفي البيض والماء واجمعيها واتركيها في الثلاجة 30 دقيقة.',
  'Un, tuz ve tereyağını ovalayın, kaşarı ekleyin.': 'افركي الدقيق والملح والزبدة وأضيفي القشقوان.',
  'Un, tuz, karbonat ve soğuk sıvıyla akışkan hamur yapın.': 'اصنعي عجينة سائلة من الدقيق والملح والبيكربونات والسائل البارد.',
  'Un, yumurta sarısı ve tuzla yumuşak hamur yapın; fazla yoğurmayın.': 'اصنعي عجينة طرية بالدقيق وصفار البيض والملح؛ دون الإكثار من العجن.',
  'Un, şeker ve yulafı karıştırın, soğuk tereyağını ekleyip kum kıvamına gelene kadar ovalayın.': 'اخلطي الدقيق والسكر والشوفان وأضيفي الزبدة الباردة وافركيها حتى تصبح كالرمل.',
  'Una, sonra çırpılmış yumurtaya bulayın.': 'غلّفيها بالدقيق ثم بالبيض المخفوق.',
  'Una, yumurtaya ve galeta ununa bulayın.': 'غلّفيه بالدقيق والبيض والبقسماط.',
  'Unları, maya, şeker ve tuzu karıştırın; su ve 2 yemek kaşığı zeytinyağıyla 8 dakika yoğurun.': 'اخلطي الدقيق والخميرة والسكر والملح؛ واعجنيها بالماء وملعقتين كبيرتين من زيت الزيتون 8 دقائق.',
  'Unu azar azar ekleyip ele yapışmayan yumuşak bir hamur yoğurun.': 'أضيفي الدقيق تدريجيًا واعجني عجينة طرية لا تلتصق باليد.',
  'Unu ekleyip 1 dakika kavurun, sütü çırparak azar azar ilave edin ve koyulaşana kadar 3 dakika karıştırın.': 'أضيفي الدقيق وقلّبيه دقيقة ثم أضيفي الحليب تدريجيًا مع الخفق وقلّبي 3 دقائق حتى يتكثف.',
  'Unu ekleyip bir dakika karıştırın; suyu azar azar ilave edin.': 'أضيفي الدقيق وقلّبي دقيقة؛ ثم أضيفي الماء تدريجيًا.',
  'Unu ekleyip kısa süre kavurun; rendelenmiş domates ve köz biberi ilave edin.': 'أضيفي الدقيق وحمّصيه قليلًا؛ ثم أضيفي الطماطم المبشورة والفلفل المشوي.',
  'Unu fazla bulaştırmayın; silkeleyin.': 'لا تكثري من الدقيق؛ انفضي الزائد.',
  'Unu katıp kısa süre kavurun.': 'أضيفي الدقيق وحمّصيه قليلًا.',
