  'Yetişkin kadınlar için günlük toplam sıvı ihtiyacı yaklaşık 2–2,5 litredir; sıcak havada, gebelikte ve emzirmede artar.': 'تحتاج المرأة البالغة إلى نحو 2–2.5 لتر من السوائل يوميًا إجمالًا؛ وأكثر في الحر والحمل والرضاعة.',
  'Yetişkin kontrollü su': 'ماء تحت إشراف شخص بالغ',
  'Yetişkin sürekli gözetiminde uygulayın. Küçük parçalar, kopabilen nesneler, ipler ve boğulma riski oluşturan malzemeler kullanmayın. Bebek istemezse durun.': 'قومي بذلك تحت إشراف دائم من شخص بالغ. لا تستخدمي القطع الصغيرة أو الأشياء التي قد تنفصل أو الخيوط أو المواد التي تشكل خطر اختناق. توقفي إذا لم يرغب الطفل.',
