  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'لا تتركيه وحده على الأسطح المرتفعة. أبعدي القطع الصغيرة والأسلاك والأدوية والمشروبات الساخنة؛ واستخدمي مقعد سيارة مناسبًا.',
